            "passage": "他下班回家，已经快十二点了。钥匙插进锁孔，转了两圈，咔哒一声，门开了。他随手把包放在玄关的矮柜上，没开大灯，只借着冰箱的光，从里面拿出两个鸡蛋、半棵白菜、一小碗剩饭。打蛋的时候，他故意放轻了动作，筷子在碗沿碰出很轻的响，怕吵醒里屋睡着的人。油热了，他先倒一半蛋液进去，滋啦一声，那股香气一下子窜上来，把他一天里的疲惫都熨平了。他把剩饭倒进去，翻炒，加白菜，加酱油，动作熟稔得像排练过千百遍。出锅前，他关小了火，又往锅里加了一点热水，让饭粒都沾上汤汁。他就着碗，站在灶台边，一口一口，慢慢吃完这碗一个人的夜宵。夜很静，只有他吃饭的声音，和窗外偶尔驶过的车声。",
            "analysis": "长语段写动作，靠「连续动词 + 克制的旁白」推进叙事。开锁、放包、拿菜、打蛋、翻炒、出锅、吃完，动作链完整，中间用「放轻动作怕吵醒人」「滋啦一声熨平疲惫」这类克制的情感点插入，让机械的动作有了温度。写长动作，要让读者跟着你的手走完整个过程。",
            "prompt": "写一个人深夜回家做一件事（做饭/整理/看书），用「完整动作链 + 一两处克制的情感点」完成整段（200字以上）。"
